@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_camera_instruction_is_packet_300(version):
    assert version.PACKETS[300] is version.CameraInstructionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_instruction_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_instruction_decodes_from_its_golden(packet, golden):
    assert v2225.CameraInstructionPacket.from_bytes(golden) == packet


def test_a_spline_with_an_empty_curve_still_writes_the_three_list_prefixes():
    assert len(bytes(EMPTY_SPLINE)) == 9 + 4 + 1 + 3 + 1 + 1


def test_a_spline_with_an_empty_curve_round_trips():
    assert v2225.CameraInstructionPacket.from_bytes(bytes(EMPTY_SPLINE)) == EMPTY_SPLINE
